"use client";

import { useState } from "react";
import { ArrowUpRight, Check, Globe, Pause, Play, Plus, RefreshCw, Search, Send, Users, Zap } from "lucide-react";
import type {
  AppRecord,
  Campaign,
  DealRecord,
  DealStage,
  LeadSource,
  PersonRecord,
  ScheduledWork,
  WorkspaceState,
} from "@/lib/domain";

export type PlatformViewName = "company" | "chat" | "scheduled" | "dashboard" | "people" | "pipeline" | "lead-data" | "campaigns" | "keywords" | "inbound" | "apps";
type Mutation = (action: string, payload?: Record<string, unknown>, success?: string) => Promise<WorkspaceState | null>;

function Heading({ eyebrow, title, subtitle, children }: { eyebrow: string; title: string; subtitle: string; children?: React.ReactNode }) {
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1 className="page-title">{title}</h1><p className="page-subtitle">{subtitle}</p></div>{children ? <div className="heading-actions">{children}</div> : null}</div>;
}

function Panel({ title, caption, children }: { title: string; caption?: string; children: React.ReactNode }) {
  return <section className="panel"><div className="panel-header"><div><div className="panel-title">{title}</div>{caption ? <div className="panel-caption">{caption}</div> : null}</div></div>{children}</section>;
}

function Empty({ children }: { children: React.ReactNode }) {
  return <div className="empty-state">{children}</div>;
}

function formatDate(value: string | null) {
  if (!value) return "Never";
  return new Date(value).toLocaleString([], { dateStyle: "medium", timeStyle: "short" });
}

function Metric({ label, value, detail }: { label: string; value: string | number; detail: string }) {
  return <div className="metric"><div className="metric-label">{label}</div><div className="metric-value">{value}</div><div className="metric-note">{detail}</div></div>;
}

function CompanyView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ industry: state.profile.industry, website: state.profile.website || "", description: state.profile.description, idealCustomer: state.profile.idealCustomer, brandVoice: state.profile.brandVoice, timezone: state.profile.timezone });
  const save = (event: React.FormEvent) => { event.preventDefault(); void mutate("update-profile", form, "Company context saved for every operator."); };
  return <><Heading eyebrow="Company" title="One source of truth for the company." subtitle="Every employee, mission, campaign, and inbound agent reads this context. Change it once; the whole workspace updates."><span className="status-pill live"><span className="status-dot" />{state.workspace.plan}</span></Heading><div className="subpage-grid"><Panel title="Company context" caption={`Workspace boundary · ${state.workspace.id}`}><form className="form-card" onSubmit={save}><div className="form-grid"><div className="field"><label htmlFor="company-industry">Industry</label><input id="company-industry" value={form.industry} onChange={(event) => setForm({ ...form, industry: event.target.value })} placeholder="e.g. Digital product studio" /></div><div className="field"><label htmlFor="company-website">Website</label><input id="company-website" type="url" value={form.website} onChange={(event) => setForm({ ...form, website: event.target.value })} placeholder="https://…" /></div></div><div className="field"><label htmlFor="company-description">What the company does</label><textarea id="company-description" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="The short, factual company brief employees should use." /></div><div className="field"><label htmlFor="company-icp">Ideal customer</label><textarea id="company-icp" value={form.idealCustomer} onChange={(event) => setForm({ ...form, idealCustomer: event.target.value })} placeholder="Who is a strong fit, and why?" /></div><div className="field"><label htmlFor="company-voice">Brand voice</label><textarea id="company-voice" value={form.brandVoice} onChange={(event) => setForm({ ...form, brandVoice: event.target.value })} /></div><div className="form-grid"><div className="field"><label htmlFor="company-timezone">Timezone</label><input id="company-timezone" value={form.timezone} onChange={(event) => setForm({ ...form, timezone: event.target.value })} placeholder="Asia/Kolkata" /></div><div className="field"><label>Runtime</label><div className="code-value">{state.workspace.region} · {state.workspace.model}</div></div></div><button className="button-primary" type="submit">Save company context <Check size={13} /></button></form></Panel><Panel title="Workspace map" caption="Persisted objects in this company"><div className="metric-grid"><Metric label="Employees" value={state.employees.length} detail="local operators" /><Metric label="Knowledge" value={state.documents.length} detail="indexed sources" /><Metric label="Missions" value={state.missions.length} detail="owned work items" /><Metric label="People" value={state.people.length + state.lists.reduce((total, list) => total + list.rows.length, 0)} detail="known prospects" /><Metric label="Inbound" value={state.inboundAgents.length} detail="agents" /><Metric label="Apps" value={state.apps.length} detail="workspace tools" /></div><div className="setting-row"><div><div className="setting-name">Owner boundary</div><div className="setting-description">Every request is resolved from the authenticated Blueblood identity and this workspace ID.</div></div><div className="code-value">{state.workspace.id}</div></div></Panel></div></>;
}

function ChatView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const liveEmployees = state.employees.filter((employee) => employee.status === "live");
  const [employeeId, setEmployeeId] = useState(liveEmployees[0]?.id || state.employees[0]?.id || "");
  const [message, setMessage] = useState("");
  const conversation = state.conversations.find((item) => item.employeeId === employeeId);
  const employee = state.employees.find((item) => item.id === employeeId);
  const send = (event: React.FormEvent) => {
    event.preventDefault();
    const text = message.trim();
    if (!text || !employeeId) return;
    setMessage("");
    void mutate("chat", { employeeId, message: text }, "Reply grounded in scoped workspace knowledge.");
  };
  return <><Heading eyebrow="Chat" title="Talk to the operator that owns the work." subtitle="This is a real persisted conversation. Responses run on the Dell worker, cite retrieved knowledge, and consume the workspace AI budget."><div className="server-status"><span className="status-dot" />Local model</div></Heading><div className="chat-layout"><Panel title={employee ? `${employee.name} · ${employee.title}` : "Choose an employee"} caption="Company-scoped memory"><div className="field"><label htmlFor="chat-employee">Operator</label><select id="chat-employee" value={employeeId} onChange={(event) => setEmployeeId(event.target.value)}>{state.employees.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.name} · {candidate.title}</option>)}</select></div><div className="chat-history">{conversation?.messages.length ? conversation.messages.map((item) => <div className={`chat-bubble ${item.role}`} key={item.id}><div>{item.content}</div>{item.citations?.length ? <small>Sources: {item.citations.join(" · ")}</small> : null}</div>) : <Empty>Ask a concrete question. The answer and its sources will be stored here.</Empty>}</div><form className="chat-compose" onSubmit={send}><textarea value={message} onChange={(event) => setMessage(event.target.value)} placeholder="What decision needs to move next?" aria-label="Chat message" /><button className="button-primary" type="submit" disabled={!message.trim() || !employeeId}>Send <Send size={13} /></button></form></Panel><Panel title="Operator contract" caption="What this chat will and will not do"><div className="list-stack"><div className="list-item"><div><div className="list-title">Grounded retrieval</div><div className="list-desc">The operator receives only the employee prompt and documents attached to this workspace.</div></div><span className="status-pill live">scoped</span></div><div className="list-item"><div><div className="list-title">Actionable ending</div><div className="list-desc">Responses are scored for evidence, ownership, and a next action before they are saved.</div></div><span className="status-pill live">scored</span></div><div className="list-item"><div><div className="list-title">No provider lock-in</div><div className="list-desc">The worker uses Ollama on the Dell. Swap the model through the deployment environment.</div></div><span className="status-pill live">open</span></div></div></Panel></div></>;
}

function ScheduledView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ name: "", description: "", employeeId: state.employees[0]?.id || "", cadence: "daily" as ScheduledWork["cadence"], activeHoursStart: "09:00", activeHoursEnd: "17:00", weekdays: [0, 1, 2, 3, 4, 5, 6] });
  const create = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-schedule", form, `${form.name} is now scheduled.`).then((saved) => { if (saved) setForm({ ...form, name: "", description: "" }); }); };
  return <><Heading eyebrow="Scheduled" title="Give work a clock and an owner." subtitle="Recurring work is persisted in the workspace and runs through the same Dell heartbeat. Every run leaves a trace, score, and next action."><span className="server-status"><Zap size={13} color="var(--mint)" />Heartbeat-backed</span></Heading><div className="subpage-grid"><Panel title="Create scheduled work" caption="No hidden cron; the task is visible and pausable"><form className="form-card" onSubmit={create}><div className="field"><label htmlFor="schedule-name">Name</label><input id="schedule-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Daily pipeline review" /></div><div className="field"><label htmlFor="schedule-description">Task</label><textarea id="schedule-description" required value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="Review the pipeline and write the next owned actions." /></div><div className="form-grid"><div className="field"><label htmlFor="schedule-employee">Owner</label><select id="schedule-employee" value={form.employeeId} onChange={(event) => setForm({ ...form, employeeId: event.target.value })}><option value="">Use first live operator</option>{state.employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.name}</option>)}</select></div><div className="field"><label htmlFor="schedule-cadence">Cadence</label><select id="schedule-cadence" value={form.cadence} onChange={(event) => setForm({ ...form, cadence: event.target.value as ScheduledWork["cadence"] })}><option value="once">Run once</option><option value="every 15m">Every 15 minutes</option><option value="hourly">Hourly</option><option value="daily">Daily</option><option value="weekly">Weekly</option></select></div></div><div className="form-grid"><div className="field"><label htmlFor="schedule-start">Active from</label><input id="schedule-start" type="time" value={form.activeHoursStart} onChange={(event) => setForm({ ...form, activeHoursStart: event.target.value })} /></div><div className="field"><label htmlFor="schedule-end">Active until</label><input id="schedule-end" type="time" value={form.activeHoursEnd} onChange={(event) => setForm({ ...form, activeHoursEnd: event.target.value })} /></div></div><div className="field"><label>Run on</label><div className="form-actions">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day, index) => <label className="checkbox-row" key={day}><input type="checkbox" checked={form.weekdays.includes(index)} onChange={(event) => setForm({ ...form, weekdays: event.target.checked ? [...form.weekdays, index].sort() : form.weekdays.filter((candidate) => candidate !== index) })} />{day}</label>)}</div></div><button className="button-primary" type="submit"><Plus size={13} />Create schedule</button></form></Panel><Panel title="Active rhythm" caption={`${state.schedules.filter((schedule) => schedule.active).length} active schedule${state.schedules.filter((schedule) => schedule.active).length === 1 ? "" : "s"}`}><div className="list-stack">{state.schedules.length ? state.schedules.map((schedule) => <ScheduleRow key={schedule.id} schedule={schedule} state={state} mutate={mutate} />) : <Empty>Create the first recurring task to give the workspace a rhythm.</Empty>}</div></Panel></div></>;
}

function ScheduleRow({ schedule, state, mutate }: { schedule: ScheduledWork; state: WorkspaceState; mutate: Mutation }) {
  const owner = state.employees.find((employee) => employee.id === schedule.employeeId);
  return <div className="list-item"><div><div className="list-title">{schedule.name} <span className={`status-pill ${schedule.active ? "live" : "paused"}`}>{schedule.active ? "active" : "paused"}</span></div><div className="list-desc">{schedule.description}</div><div className="list-meta">{schedule.cadence} · owner {owner?.name || "first live operator"} · next {formatDate(schedule.nextRunAt)} · {schedule.runCount} run{schedule.runCount === 1 ? "" : "s"}</div><div className="list-meta">{schedule.activeHours ? `${schedule.activeHours.start}–${schedule.activeHours.end}` : "all hours"} · {(schedule.weekdays || [0, 1, 2, 3, 4, 5, 6]).length}/7 days · previous output {schedule.lastOutput ? "available" : "none"}</div>{schedule.lastOutput ? <div className="prompt-box mission-output">{schedule.lastOutput}</div> : null}</div><div className="row-actions"><button className="small-button" onClick={() => void mutate("run-scheduled", { scheduleId: schedule.id }, `${schedule.name} completed.`)}><Play size={11} />Run now</button><button className="small-button" onClick={() => void mutate("toggle-schedule", { scheduleId: schedule.id, active: !schedule.active }, `${schedule.name} ${schedule.active ? "paused" : "resumed"}.`)}>{schedule.active ? <Pause size={11} /> : <Play size={11} />}{schedule.active ? "Pause" : "Resume"}</button></div></div>;
}

function DashboardView({ state }: { state: WorkspaceState }) {
  const completed = state.missions.filter((mission) => mission.status === "completed").length;
  const reviewed = state.content.filter((content) => ["approved", "scheduled", "published"].includes(content.status)).length;
  const qualified = state.people.filter((person) => person.status === "qualified").length + state.lists.flatMap((list) => list.rows).filter((row) => row.status === "enriched").length;
  const score = state.employees.length ? Math.round(state.employees.reduce((total, employee) => total + employee.score, 0) / state.employees.length) : 0;
  const openPipeline = state.deals.filter((deal) => !["won", "lost"].includes(deal.stage));
  const pipelineValue = openPipeline.reduce((sum, deal) => sum + deal.amount, 0);
  return <><Heading eyebrow="Dashboard" title="See where work is moving—and where it is stuck." subtitle="These are workspace-derived metrics from persisted employees, runs, missions, content, people, pipeline, and support. Nothing here is an illustrative number."><span className="server-status"><span className="status-dot" />Live workspace state</span></Heading><div className="metric-grid"><Metric label="Operator score" value={score || "—"} detail="average latest score" /><Metric label="Mission completion" value={state.missions.length ? `${Math.round((completed / state.missions.length) * 100)}%` : "—"} detail={`${completed}/${state.missions.length} completed`} /><Metric label="Content shipped" value={reviewed} detail="approved or published" /><Metric label="Qualified people" value={qualified} detail="public evidence captured" /><Metric label="Open pipeline" value={money(pipelineValue)} detail={`${openPipeline.length} active opportunities`} /><Metric label="AI credits" value={state.workspace.aiCredits.remaining} detail={`of ${state.workspace.aiCredits.limit} remaining`} /><Metric label="Open tickets" value={state.tickets.filter((ticket) => ticket.status !== "resolved").length} detail="SLA-aware queue" /></div><div className="subpage-grid"><Panel title="Work in motion" caption="Latest persisted activity"><div className="activity-list">{state.activity.slice(0, 12).map((item) => <div className="activity-row" key={item.id}><div className="activity-icon"><Zap size={14} /></div><div><div className="activity-title">{item.title}</div><div className="activity-detail">{item.detail}</div></div><time>{formatDate(item.createdAt)}</time></div>)}</div>{!state.activity.length ? <Empty>Activity appears as soon as the first workspace action runs.</Empty> : null}</Panel><Panel title="Bottlenecks" caption="Concrete next actions"><div className="list-stack">{state.missions.filter((mission) => mission.status !== "completed").slice(0, 5).map((mission) => <div className="list-item" key={mission.id}><div><div className="list-title">{mission.title}</div><div className="list-desc">{mission.status.replace("_", " ")} · {mission.priority} priority</div></div><span className="status-pill paused">needs work</span></div>)}{!state.missions.some((mission) => mission.status !== "completed") ? <Empty>No open mission bottlenecks.</Empty> : null}</div></Panel></div></>;
}

const dealStages: Array<{ id: DealStage; label: string }> = [
  { id: "lead", label: "Lead" },
  { id: "qualified", label: "Qualified" },
  { id: "proposal", label: "Proposal" },
  { id: "won", label: "Won" },
  { id: "lost", label: "Lost" },
];

function money(value: number, currency = "USD") {
  return new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: 0 }).format(value);
}

function PipelineView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ name: "", company: "", personId: "", amount: "", stage: "lead" as DealStage, ownerEmployeeId: state.employees.find((employee) => employee.status === "live")?.id || "", source: "manual", nextAction: "", closeDate: "", notes: "" });
  const openDeals = state.deals.filter((deal) => !["won", "lost"].includes(deal.stage));
  const openValue = openDeals.reduce((sum, deal) => sum + deal.amount, 0);
  const weightedValue = openDeals.reduce((sum, deal) => sum + (deal.amount * deal.probability / 100), 0);
  const wonValue = state.deals.filter((deal) => deal.stage === "won").reduce((sum, deal) => sum + deal.amount, 0);
  const create = (event: React.FormEvent) => {
    event.preventDefault();
    void mutate("create-deal", { ...form, amount: Number(form.amount || 0), personId: form.personId || null, ownerEmployeeId: form.ownerEmployeeId || null, closeDate: form.closeDate || null }, `${form.name} entered the pipeline.`).then((saved) => {
      if (saved) setForm({ ...form, name: "", company: "", personId: "", amount: "", nextAction: "", closeDate: "", notes: "" });
    });
  };
  return <><Heading eyebrow="Revenue / Pipeline" title="Turn interest into owned revenue." subtitle="Every opportunity has a value, stage, owner, next action, and history. This is the local CRM loop—no fake attribution or hidden provider state."><span className="server-status"><span className="status-dot" />{state.deals.length} opportunities</span></Heading><div className="metric-grid"><Metric label="Open pipeline" value={money(openValue)} detail={`${openDeals.length} active opportunities`} /><Metric label="Weighted value" value={money(weightedValue)} detail="stage probability applied" /><Metric label="Won" value={money(wonValue)} detail={`${state.deals.filter((deal) => deal.stage === "won").length} closed-won`} /><Metric label="Next actions" value={state.deals.filter((deal) => deal.stage !== "lost" && deal.stage !== "won" && deal.nextAction.trim()).length} detail="opportunities with an owner action" /></div><div className="subpage-grid"><Panel title="Add opportunity" caption="Create a real deal from a person, list row, or manual source"><form className="form-card" onSubmit={create}><div className="form-grid"><div className="field"><label htmlFor="deal-name">Opportunity</label><input id="deal-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Website operations retainer" /></div><div className="field"><label htmlFor="deal-company">Company</label><input id="deal-company" required value={form.company} onChange={(event) => setForm({ ...form, company: event.target.value })} placeholder="Acme Inc." /></div></div><div className="form-grid"><div className="field"><label htmlFor="deal-amount">Value</label><input id="deal-amount" type="number" min="0" step="1" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} placeholder="12000" /></div><div className="field"><label htmlFor="deal-stage">Stage</label><select id="deal-stage" value={form.stage} onChange={(event) => setForm({ ...form, stage: event.target.value as DealStage })}>{dealStages.map((stage) => <option key={stage.id} value={stage.id}>{stage.label}</option>)}</select></div></div><div className="form-grid"><div className="field"><label htmlFor="deal-owner">Owner</label><select id="deal-owner" value={form.ownerEmployeeId} onChange={(event) => setForm({ ...form, ownerEmployeeId: event.target.value })}><option value="">Unassigned</option>{state.employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.name}</option>)}</select></div><div className="field"><label htmlFor="deal-person">Person</label><select id="deal-person" value={form.personId} onChange={(event) => setForm({ ...form, personId: event.target.value })}><option value="">No linked person</option>{state.people.map((person) => <option key={person.id} value={person.id}>{person.name} · {person.company}</option>)}</select></div></div><div className="form-grid"><div className="field"><label htmlFor="deal-source">Source</label><input id="deal-source" value={form.source} onChange={(event) => setForm({ ...form, source: event.target.value })} placeholder="inbound, referral, list" /></div><div className="field"><label htmlFor="deal-close-date">Target close</label><input id="deal-close-date" type="date" value={form.closeDate} onChange={(event) => setForm({ ...form, closeDate: event.target.value })} /></div></div><div className="field"><label htmlFor="deal-next-action">Next action</label><input id="deal-next-action" required value={form.nextAction} onChange={(event) => setForm({ ...form, nextAction: event.target.value })} placeholder="Send the scoped proposal by Friday" /></div><div className="field"><label htmlFor="deal-notes">Notes</label><textarea id="deal-notes" value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} placeholder="Evidence, blockers, or buying context." /></div><button className="button-primary" type="submit"><Plus size={13} />Add opportunity</button></form></Panel><Panel title="Pipeline board" caption="Move a deal only when the evidence changes"><div className="pipeline-board">{dealStages.map((stage) => <section className="pipeline-column" key={stage.id}><div className="pipeline-column-head"><div className="panel-title">{stage.label}</div><span className="status-pill">{state.deals.filter((deal) => deal.stage === stage.id).length}</span></div><div className="pipeline-column-value">{money(state.deals.filter((deal) => deal.stage === stage.id).reduce((sum, deal) => sum + deal.amount, 0))}</div><div className="list-stack">{state.deals.filter((deal) => deal.stage === stage.id).map((deal) => <DealCard key={deal.id} deal={deal} state={state} mutate={mutate} />)}{!state.deals.some((deal) => deal.stage === stage.id) ? <div className="pipeline-empty">No opportunities</div> : null}</div></section>)}</div></Panel></div></>;
}

function DealCard({ deal, state, mutate }: { deal: DealRecord; state: WorkspaceState; mutate: Mutation }) {
  const [nextAction, setNextAction] = useState(deal.nextAction);
  const [stage, setStage] = useState<DealStage>(deal.stage);
  const owner = state.employees.find((employee) => employee.id === deal.ownerEmployeeId);
  const save = () => void mutate("update-deal", { dealId: deal.id, nextAction, stage, stageNote: "Updated from pipeline board" }, `${deal.name} was updated.`);
  return <article className="pipeline-card"><div className="list-title">{deal.name}</div><div className="list-desc">{deal.company} · {money(deal.amount, deal.currency)}</div><div className="list-meta">{owner?.name || "Unassigned"} · {deal.probability}% likely · {deal.source}</div>{deal.closeDate ? <div className="list-meta">Target close · {deal.closeDate}</div> : null}<div className="field"><label htmlFor={`deal-stage-${deal.id}`}>Stage</label><select id={`deal-stage-${deal.id}`} value={stage} onChange={(event) => setStage(event.target.value as DealStage)}>{dealStages.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.label}</option>)}</select></div><div className="field"><label htmlFor={`deal-action-${deal.id}`}>Next action</label><input id={`deal-action-${deal.id}`} value={nextAction} onChange={(event) => setNextAction(event.target.value)} /></div><button className="small-button ready" type="button" onClick={save}>Save update</button>{deal.stageHistory.length > 1 ? <div className="list-meta">History · {deal.stageHistory.length} changes</div> : null}</article>;
}

function PeopleView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ name: "", email: "", title: "", company: "", location: "", tags: "" });
  const create = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-person", form, `${form.name} was added to People.`).then((saved) => { if (saved) setForm({ name: "", email: "", title: "", company: "", location: "", tags: "" }); }); };
  return <><Heading eyebrow="Find & Enrich / People" title="A unified people workspace." subtitle="Add known contacts, qualify them against public company evidence, then move qualified people into a Smart List for real workflows."><span className="server-status"><Users size={13} color="var(--mint)" />{state.people.length} people</span></Heading><div className="subpage-grid"><Panel title="Add a person" caption="No scraped or purchased data is silently invented"><form className="form-card" onSubmit={create}><div className="form-grid"><div className="field"><label htmlFor="person-name">Name</label><input id="person-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></div><div className="field"><label htmlFor="person-email">Business email</label><input id="person-email" type="email" required value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></div></div><div className="form-grid"><div className="field"><label htmlFor="person-title">Title</label><input id="person-title" value={form.title} onChange={(event) => setForm({ ...form, title: event.target.value })} /></div><div className="field"><label htmlFor="person-company">Company</label><input id="person-company" required value={form.company} onChange={(event) => setForm({ ...form, company: event.target.value })} /></div></div><div className="form-grid"><div className="field"><label htmlFor="person-location">Location</label><input id="person-location" value={form.location} onChange={(event) => setForm({ ...form, location: event.target.value })} /></div><div className="field"><label htmlFor="person-tags">Tags</label><input id="person-tags" value={form.tags} onChange={(event) => setForm({ ...form, tags: event.target.value })} placeholder="founder, ICP" /></div></div><button className="button-primary" type="submit"><Plus size={13} />Add person</button></form></Panel><Panel title="People" caption="Qualification consumes 2 Data Credits and fetches the public company site"><div className="table-wrap"><table className="data-table"><thead><tr><th>Person</th><th>Company</th><th>Score</th><th>Status</th><th>Action</th></tr></thead><tbody>{state.people.map((person) => <PersonRow key={person.id} person={person} state={state} mutate={mutate} />)}</tbody></table>{!state.people.length ? <Empty>Add a person to start a durable people record.</Empty> : null}</div></Panel></div></>;
}

function PersonRow({ person, state, mutate }: { person: PersonRecord; state: WorkspaceState; mutate: Mutation }) {
  const targetList = state.lists[0];
  const alreadyInList = state.lists.some((list) => list.rows.some((row) => row.email.toLowerCase() === person.email.toLowerCase()));
  return <tr><td><strong>{person.name}</strong><div className="list-meta">{person.email} · {person.title}</div></td><td>{person.company}<div className="list-meta">{person.location}</div></td><td><strong>{person.score || "—"}</strong></td><td><span className={`status-pill ${person.status === "qualified" ? "live" : "paused"}`}>{person.status}</span></td><td>{person.status !== "qualified" ? <button className="small-button" onClick={() => void mutate("qualify-person", { personId: person.id }, `${person.name} was qualified with public evidence.`)}><Search size={11} />Qualify</button> : alreadyInList ? <span className="small-button ready"><Check size={11} />In Smart List</span> : targetList ? <button className="small-button" onClick={() => void mutate("add-person-to-list", { personId: person.id, listId: targetList.id }, `${person.name} was added to ${targetList.name}.`)}><Plus size={11} />Add to {targetList.name}</button> : <span className="small-button">Create a Smart List</span>}</td></tr>;
}

function LeadDataView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [name, setName] = useState("");
  const [type, setType] = useState<LeadSource["type"]>("manual");
  const [listId, setListId] = useState("");
  const create = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-lead-source", { name, type, listId }, `${name} is ready.`).then((saved) => { if (saved) { setName(""); setListId(""); } }); };
  return <><Heading eyebrow="Find & Enrich / Lead Data" title="Bring sources into a qualification loop." subtitle="Every source run now does real work: it counts owned records, captures a public search result set, or points at a Smart List you can research and act on."><button className="button-secondary" onClick={() => setType("csv")}><ArrowUpRight size={13} />Use Smart Lists for CSV</button></Heading><div className="subpage-grid"><Panel title="Register a source" caption="Source metadata stays inside this workspace"><form className="form-card" onSubmit={create}><div className="field"><label htmlFor="source-name">{type === "public" ? "Search phrase" : "Source name"}</label><input id="source-name" required value={name} onChange={(event) => setName(event.target.value)} placeholder={type === "public" ? "AI-first sales teams" : "Founder referrals"} /></div><div className="field"><label htmlFor="source-type">Source type</label><select id="source-type" value={type} onChange={(event) => setType(event.target.value as LeadSource["type"])}><option value="manual">Manual People records</option><option value="csv">CSV / Smart List</option><option value="public">Public research</option></select></div>{type === "csv" ? <div className="field"><label htmlFor="source-list">Smart List</label><select id="source-list" required value={listId} onChange={(event) => setListId(event.target.value)}><option value="">Choose a Smart List</option>{state.lists.map((list) => <option value={list.id} key={list.id}>{list.name} · {list.rows.length} rows</option>)}</select></div> : null}<button className="button-primary" type="submit"><Plus size={13} />Add source</button></form></Panel><Panel title="Sources" caption={`${state.leadSources.length} registered source${state.leadSources.length === 1 ? "" : "s"}`}><div className="list-stack">{state.leadSources.map((source) => <div className="list-item" key={source.id}><div><div className="list-title">{source.name} <span className="source-tag">{source.type}</span><span className={`status-pill ${source.status === "completed" ? "live" : source.status === "failed" ? "paused" : ""}`}>{source.status}</span></div><div className="list-desc">{source.recordCount} record{source.recordCount === 1 ? "" : "s"} · {source.lastRunAt ? `last run ${formatDate(source.lastRunAt)}` : "not run yet"}</div>{source.lastSummary ? <div className="list-meta">{source.lastSummary}</div> : null}</div><button className="small-button" onClick={() => void mutate("run-lead-source", { sourceId: source.id }, `${source.name} finished.`)}><RefreshCw size={11} />Run source</button></div>)}{!state.leadSources.length ? <Empty>Add a source to make lead acquisition visible.</Empty> : null}</div></Panel></div></>;
}

function CampaignsView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ name: "", type: "content" as Campaign["type"], audience: "", contentId: "", listId: "", subject: "", body: "" });
  const isBroadcast = form.type === "broadcast";
  const create = (event: React.FormEvent) => {
    event.preventDefault();
    void mutate("create-campaign", form, `${form.name} was created.`).then((saved) => {
      if (saved) setForm({ name: "", type: "content", audience: "", contentId: "", listId: "", subject: "", body: "" });
    });
  };
  const sendBroadcast = (campaign: Campaign) => {
    if (!window.confirm(`Send ${campaign.name} to its enriched Smart List through Gmail?`)) return;
    void mutate("send-campaign", { campaignId: campaign.id }, `${campaign.name} finished its Gmail broadcast.`);
  };
  return <><Heading eyebrow="Engage / Campaigns" title="Campaigns with a real editorial gate." subtitle="Publish approved pages natively, or send a human-triggered Gmail broadcast to an enriched Smart List. Every recipient is safety-checked and idempotent."><span className="server-status"><Send size={13} color="var(--mint)" />Human-approved</span></Heading><div className="subpage-grid"><Panel title="Create campaign" caption={isBroadcast ? "Gmail broadcast · explicit send only" : "Native campaigns require approved content"}><form className="form-card" onSubmit={create}><div className="field"><label htmlFor="campaign-name">Name</label><input id="campaign-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></div><div className="form-grid"><div className="field"><label htmlFor="campaign-type">Type</label><select id="campaign-type" value={form.type} onChange={(event) => setForm({ ...form, type: event.target.value as Campaign["type"] })}><option value="content">Website / blog</option><option value="broadcast">Gmail broadcast</option></select></div><div className="field"><label htmlFor="campaign-audience">Audience label</label><input id="campaign-audience" value={form.audience} onChange={(event) => setForm({ ...form, audience: event.target.value })} placeholder="AI-first founders" /></div></div>{isBroadcast ? <><div className="field"><label htmlFor="campaign-list">Smart List</label><select id="campaign-list" required value={form.listId} onChange={(event) => setForm({ ...form, listId: event.target.value })}><option value="">Choose a Smart List</option>{state.lists.map((list) => <option key={list.id} value={list.id}>{list.name} · {list.rows.filter((row) => row.status === "enriched").length} enriched</option>)}</select></div><div className="field"><label htmlFor="campaign-subject">Subject</label><input id="campaign-subject" required value={form.subject} onChange={(event) => setForm({ ...form, subject: event.target.value })} placeholder="A useful update for {{companyName}}" /></div><div className="field"><label htmlFor="campaign-body">Email body</label><textarea id="campaign-body" required value={form.body} onChange={(event) => setForm({ ...form, body: event.target.value })} placeholder="Use {{firstName}}, {{companyName}}, and {{role}} for row personalization." /></div></> : <div className="field"><label htmlFor="campaign-content">Website or blog content</label><select id="campaign-content" required value={form.contentId} onChange={(event) => setForm({ ...form, contentId: event.target.value })}><option value="">Choose approved content</option>{state.content.filter((content) => content.channel === "website" || content.channel === "blog").map((content) => <option key={content.id} value={content.id}>{content.title} · {content.status}</option>)}</select></div>}<button className="button-primary" type="submit"><Plus size={13} />Create campaign</button></form></Panel><Panel title="Campaign calendar" caption="Persisted campaign state"><div className="list-stack">{state.campaigns.map((campaign) => <div className="list-item" key={campaign.id}><div><div className="list-title">{campaign.name} <span className={`status-pill ${campaign.status === "scheduled" ? "live" : campaign.status === "completed" ? "live" : "paused"}`}>{campaign.status}</span></div><div className="list-desc">{campaign.type} · {campaign.audience || "workspace audience"}{campaign.scheduledAt ? ` · ${formatDate(campaign.scheduledAt)}` : ""}{campaign.lastResult ? ` · ${campaign.lastResult}` : ""}</div></div>{campaign.status === "draft" && campaign.type === "broadcast" ? <button className="small-button ready" onClick={() => sendBroadcast(campaign)}><Send size={11} />Send broadcast</button> : campaign.status === "draft" ? <button className="small-button" onClick={() => void mutate("schedule-campaign", { campaignId: campaign.id }, `${campaign.name} was scheduled for native publication.`)}><Play size={11} />Schedule</button> : <span className="small-button ready"><Check size={11} />{campaign.status === "completed" ? "Completed" : "Waiting for Dell"}</span>}</div>)}{!state.campaigns.length ? <Empty>Create a campaign to schedule a grounded page publication.</Empty> : null}</div></Panel></div></>;
}

function KeywordsView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [keyword, setKeyword] = useState("");
  const create = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-keyword-monitor", { keyword }, `${keyword} is now monitored.`).then((saved) => { if (saved) setKeyword(""); }); };
  return <><Heading eyebrow="Engage / Keyword Monitoring" title="Watch the public web for a signal." subtitle="Checks run against a public search endpoint from the Dell and persist the result summary. Pause a monitor when the signal is no longer relevant."><span className="server-status"><Globe size={13} color="var(--mint)" />Public web</span></Heading><div className="subpage-grid"><Panel title="Add a monitor" caption="No paid data provider required"><form className="form-card" onSubmit={create}><div className="field"><label htmlFor="monitor-keyword">Keyword or phrase</label><input id="monitor-keyword" required value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="Perpendicular open source" /></div><button className="button-primary" type="submit"><Plus size={13} />Monitor keyword</button></form></Panel><Panel title="Monitors" caption="Run a check when you want fresh evidence"><div className="list-stack">{state.keywordMonitors.map((monitor) => <div className="list-item" key={monitor.id}><div><div className="list-title">{monitor.keyword} <span className={`status-pill ${monitor.status === "active" ? "live" : "paused"}`}>{monitor.status}</span></div><div className="list-desc">{monitor.matchCount} matches · {monitor.lastCheckedAt ? formatDate(monitor.lastCheckedAt) : "not checked"}</div>{monitor.latestSummary ? <div className="list-meta">{monitor.latestSummary}</div> : null}</div><div className="row-actions"><button className="small-button" disabled={monitor.status !== "active"} onClick={() => void mutate("check-keyword", { monitorId: monitor.id }, `${monitor.keyword} was checked.`)}><RefreshCw size={11} />Check</button><button className="small-button" onClick={() => void mutate("toggle-keyword-monitor", { monitorId: monitor.id, active: monitor.status !== "active" }, `${monitor.keyword} ${monitor.status === "active" ? "paused" : "resumed"}.`)}>{monitor.status === "active" ? <Pause size={11} /> : <Play size={11} />}</button></div></div>)}{!state.keywordMonitors.length ? <Empty>Add a keyword to start a real public check.</Empty> : null}</div></Panel></div></>;
}

function InboundView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [agentName, setAgentName] = useState("");
  const [siteName, setSiteName] = useState("");
  const [headline, setHeadline] = useState("");
  const [body, setBody] = useState("");
  const [agentId, setAgentId] = useState(() => state.inboundAgents.find((agent) => agent.status === "live")?.id || "");
  const createAgent = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-inbound-agent", { name: agentName, employeeId: state.employees[0]?.id }, `${agentName} was created.`).then((saved) => { if (saved) setAgentName(""); }); };
  const createSite = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-site", { name: siteName, headline, body, agentId }, `${siteName} was created.`).then((saved) => { if (saved) { setSiteName(""); setHeadline(""); setBody(""); } }); };
  return <><Heading eyebrow="Inbound" title="Turn attention into a grounded conversation." subtitle="Create an inbound agent backed by a live employee, then publish a simple site or landing page. The existing capability-keyed widget remains available for embedding anywhere you control."><span className="server-status"><Globe size={13} color="var(--mint)" />Widget + sites</span></Heading><div className="subpage-grid"><Panel title="Inbound agents" caption="Agents route to a real workspace employee"><form className="form-card" onSubmit={createAgent}><div className="field"><label htmlFor="agent-name">Agent name</label><input id="agent-name" required value={agentName} onChange={(event) => setAgentName(event.target.value)} placeholder="Website operator" /></div><div className="field"><label htmlFor="agent-employee">Employee</label><select id="agent-employee" value={state.employees[0]?.id || ""} disabled>{state.employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.name} · {employee.title}</option>)}</select></div><button className="button-primary" type="submit"><Plus size={13} />Create agent</button></form><div className="list-stack">{state.inboundAgents.map((agent) => <div className="list-item" key={agent.id}><div><div className="list-title">{agent.name} <span className={`status-pill ${agent.status === "live" ? "live" : "paused"}`}>{agent.status}</span></div><div className="list-desc">{agent.channel} · {state.employees.find((employee) => employee.id === agent.employeeId)?.name || "unassigned"}</div></div><button className="small-button" onClick={() => void mutate("toggle-inbound-agent", { agentId: agent.id, active: agent.status !== "live" }, `${agent.name} is ${agent.status === "live" ? "paused" : "live"}.`)}>{agent.status === "live" ? <Pause size={11} /> : <Play size={11} />}{agent.status === "live" ? "Pause" : "Make live"}</button></div>)}</div></Panel><Panel title="Websites & landing pages" caption="Published pages are workspace records with stable slugs"><form className="form-card" onSubmit={createSite}><div className="form-grid"><div className="field"><label htmlFor="site-name">Name</label><input id="site-name" required value={siteName} onChange={(event) => setSiteName(event.target.value)} placeholder="Product page" /></div><div className="field"><label htmlFor="site-agent">Inbound agent</label><select id="site-agent" value={agentId} onChange={(event) => setAgentId(event.target.value)}><option value="">No agent attached</option>{state.inboundAgents.map((agent) => <option key={agent.id} value={agent.id}>{agent.name}</option>)}</select></div></div><div className="field"><label htmlFor="site-headline">Headline</label><input id="site-headline" required value={headline} onChange={(event) => setHeadline(event.target.value)} /></div><div className="field"><label htmlFor="site-body">Page body</label><textarea id="site-body" value={body} onChange={(event) => setBody(event.target.value)} placeholder="Explain the offer, proof, and next step in plain language." /></div><button className="button-primary" type="submit"><Plus size={13} />Create page</button></form><div className="list-stack">{state.sites.map((site) => <div className="list-item" key={site.id}><div><div className="list-title">{site.name} <span className={`status-pill ${site.status === "published" ? "live" : "paused"}`}>{site.status}</span></div><div className="list-desc">/site/{site.slug} · {site.headline}</div></div>{site.status === "published" ? <a className="small-button" href={`/site/${site.slug}`} target="_blank" rel="noreferrer">Open <ArrowUpRight size={11} /></a> : <button className="small-button" onClick={() => void mutate("publish-site", { siteId: site.id }, `${site.name} was published.`)}><Globe size={11} />Publish</button>}</div>)}{!state.sites.length ? <Empty>Create a page to make inbound work visible.</Empty> : null}</div></Panel></div></>;
}

function AppsView({ state, mutate }: { state: WorkspaceState; mutate: Mutation }) {
  const [form, setForm] = useState({ name: "", description: "", task: "", type: "workflow" as AppRecord["type"], employeeId: "" });
  const create = (event: React.FormEvent) => { event.preventDefault(); void mutate("create-app", form, `${form.name} was added.`).then((saved) => { if (saved) setForm({ name: "", description: "", task: "", type: "workflow", employeeId: "" }); }); };
  return <><Heading eyebrow="Apps" title="Build tools that actually run." subtitle="Every app is an executable contract for a local employee. Run it here, call it through REST, or expose it through MCP; every result is persisted with credits, score, and trace."><span className="server-status"><Zap size={13} color="var(--mint)" />Executable runtime</span></Heading><div className="subpage-grid"><Panel title="Create an app" caption="Save the instruction once, then run it against live workspace context"><form className="form-card" onSubmit={create}><div className="field"><label htmlFor="app-name">Name</label><input id="app-name" required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Lead brief generator" /></div><div className="field"><label htmlFor="app-description">Description</label><textarea id="app-description" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="What this tool is for." /></div><div className="field"><label htmlFor="app-task">Run instruction</label><textarea id="app-task" required value={form.task} onChange={(event) => setForm({ ...form, task: event.target.value })} placeholder="Turn the operator input into a concise, evidence-backed brief with one next action." /></div><div className="form-grid"><div className="field"><label htmlFor="app-type">Interface</label><select id="app-type" value={form.type} onChange={(event) => setForm({ ...form, type: event.target.value as AppRecord["type"] })}><option value="workflow">Workflow</option><option value="api">REST API</option><option value="mcp">MCP tool</option></select></div><div className="field"><label htmlFor="app-employee">Operator</label><select id="app-employee" value={form.employeeId} onChange={(event) => setForm({ ...form, employeeId: event.target.value })}><option value="">First live operator</option>{state.employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.name}</option>)}</select></div></div><button className="button-primary" type="submit"><Plus size={13} />Create app</button></form></Panel><Panel title="Workspace apps" caption="Drafts must be activated before they can spend AI Credits"><div className="list-stack">{state.apps.map((app) => <AppRow key={app.id} app={app} state={state} mutate={mutate} />)}{!state.apps.length ? <Empty>Create an app to make the workspace extensible without adding another service.</Empty> : null}</div></Panel></div></>;
}

function AppRow({ app, state, mutate }: { app: AppRecord; state: WorkspaceState; mutate: Mutation }) {
  const [input, setInput] = useState("");
  const operator = state.employees.find((employee) => employee.id === app.employeeId);
  return <article className="list-item"><div className="list-main"><div className="list-title">{app.name} <span className={`status-pill ${app.status === "active" ? "live" : "paused"}`}>{app.status}</span></div><div className="list-desc">{app.type} · {app.description}</div><div className="list-meta">{operator?.name || "first live operator"} · {app.runCount || 0} run{app.runCount === 1 ? "" : "s"}{app.type === "api" ? ` · POST /api/apps/${app.id}/run` : ""}</div><div className="prompt-box">{app.task || app.description}</div>{app.lastOutput ? <div className="prompt-box mission-output"><strong>Last output</strong><br />{app.lastOutput}</div> : null}</div><div className="row-actions"><input aria-label={`Input for ${app.name}`} value={input} onChange={(event) => setInput(event.target.value)} placeholder="Optional run input" disabled={app.status !== "active"} /><button className="small-button" disabled={app.status !== "active"} onClick={() => void mutate("run-app", { appId: app.id, input }, `${app.name} completed.`)}><Zap size={11} />Run</button><button className="small-button" onClick={() => void mutate("toggle-app", { appId: app.id, active: app.status !== "active" }, `${app.name} is ${app.status === "active" ? "paused" : "active"}.`)}>{app.status === "active" ? <Pause size={11} /> : <Play size={11} />}{app.status === "active" ? "Pause" : "Activate"}</button></div></article>;
}

export function PlatformView({ view, state, mutate }: { view: PlatformViewName; state: WorkspaceState; mutate: Mutation }) {
  if (view === "company") return <CompanyView state={state} mutate={mutate} />;
  if (view === "chat") return <ChatView state={state} mutate={mutate} />;
  if (view === "scheduled") return <ScheduledView state={state} mutate={mutate} />;
  if (view === "dashboard") return <DashboardView state={state} />;
  if (view === "people") return <PeopleView state={state} mutate={mutate} />;
  if (view === "pipeline") return <PipelineView state={state} mutate={mutate} />;
  if (view === "lead-data") return <LeadDataView state={state} mutate={mutate} />;
  if (view === "campaigns") return <CampaignsView state={state} mutate={mutate} />;
  if (view === "keywords") return <KeywordsView state={state} mutate={mutate} />;
  if (view === "inbound") return <InboundView state={state} mutate={mutate} />;
  return <AppsView state={state} mutate={mutate} />;
}
